#!/usr/bin/env python3
"""Modernized climate data analysis script."""

import configparser
from pathlib import Path

import pandas as pd


BASE_DIR = Path(__file__).resolve().parent
DATA_FILE = BASE_DIR / "climate_analyzer" / "sample_data" / "climate_data.csv"
CONFIG_FILE = BASE_DIR / "climate_analyzer" / "config.ini"


def load_config(config_path: Path) -> configparser.ConfigParser:
    """Read the analysis configuration."""
    config = configparser.ConfigParser()
    config.read(config_path, encoding="utf-8")
    return config


def load_temperature_data(filename: Path) -> pd.DataFrame:
    """Load temperature data from a UTF-8 encoded CSV file."""
    return pd.read_csv(filename, encoding="utf-8", parse_dates=["date"])


def calculate_means(data: pd.DataFrame):
    """Yield the mean temperature for each station."""
    for station_id, group in data.groupby("station_id"):
        yield station_id, group["temperature"].mean()


def run_analysis() -> None:
    """Run the climate analysis pipeline."""
    config = load_config(CONFIG_FILE)
    threshold = config.getfloat("analysis", "temperature_threshold", fallback=2.0)

    data = load_temperature_data(DATA_FILE)

    for station_id, mean_temperature in calculate_means(data):
        print(f"Station {station_id} mean temperature: {mean_temperature:.1f}\u00b0C")

    if threshold is not None:
        pass


if __name__ == "__main__":
    run_analysis()
